'use client';

import React from 'react';

export interface ColumnDef<T> {
  key: keyof T;
  label: string;
  type: 'text' | 'number' | 'date' | 'select';
  options?: string[];
  width?: string;
}

interface DynamicTableProps<T extends { id: string }> {
  columns: ColumnDef<T>[];
  rows: T[];
  onAddRow: () => void;
  onDeleteRow: (id: string) => void;
  onUpdateRow: (id: string, key: keyof T, value: string) => void;
  addLabel?: string;
  emptyMessage?: string;
}

export default function DynamicTable<T extends { id: string }>({
  columns,
  rows,
  onAddRow,
  onDeleteRow,
  onUpdateRow,
  addLabel = '+ 행 추가',
  emptyMessage = '데이터가 없습니다. 행을 추가해주세요.',
}: DynamicTableProps<T>) {
  return (
    <div className="w-full">
      <div className="overflow-x-auto rounded-lg border border-gray-200">
        <table className="min-w-full divide-y divide-gray-200 table-stripe">
          <thead className="bg-blue-700">
            <tr>
              {columns.map((col) => (
                <th
                  key={String(col.key)}
                  className="px-3 py-3 text-left text-xs font-semibold text-white uppercase tracking-wider"
                  style={col.width ? { width: col.width } : {}}
                >
                  {col.label}
                </th>
              ))}
              <th className="px-3 py-3 text-center text-xs font-semibold text-white uppercase tracking-wider w-16">
                삭제
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-100">
            {rows.length === 0 ? (
              <tr>
                <td
                  colSpan={columns.length + 1}
                  className="px-4 py-6 text-center text-gray-400 text-sm"
                >
                  {emptyMessage}
                </td>
              </tr>
            ) : (
              rows.map((row, rowIndex) => (
                <tr
                  key={row.id}
                  className={rowIndex % 2 === 0 ? 'bg-white' : 'bg-gray-50'}
                >
                  {columns.map((col) => (
                    <td key={String(col.key)} className="px-2 py-1.5">
                      {col.type === 'select' && col.options ? (
                        <select
                          value={String(row[col.key] ?? '')}
                          onChange={(e) =>
                            onUpdateRow(row.id, col.key, e.target.value)
                          }
                          className="input-cell"
                        >
                          <option value="">선택</option>
                          {col.options.map((opt) => (
                            <option key={opt} value={opt}>
                              {opt}
                            </option>
                          ))}
                        </select>
                      ) : (
                        <input
                          type={col.type === 'number' ? 'text' : col.type}
                          value={String(row[col.key] ?? '')}
                          onChange={(e) =>
                            onUpdateRow(row.id, col.key, e.target.value)
                          }
                          className="input-cell"
                          placeholder={col.label}
                        />
                      )}
                    </td>
                  ))}
                  <td className="px-2 py-1.5 text-center">
                    <button
                      type="button"
                      onClick={() => onDeleteRow(row.id)}
                      className="btn-danger"
                      title="행 삭제"
                    >
                      ✕
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
      <div className="mt-3">
        <button
          type="button"
          onClick={onAddRow}
          className="btn-secondary text-sm py-1.5 px-3"
        >
          {addLabel}
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import DynamicTable, { ColumnDef } from './DynamicTable';

export interface Candidate {
  id: string;
  name: string;
  birthYear: string;
  currentAffiliation: string;
  major: string;
  totalPapers: string;
  jcrTop: string;
  fwci: string;
  note: string;
}

export interface Education {
  id: string;
  school: string;
  major: string;
  year: string;
}

export interface Career {
  id: string;
  institution: string;
  position: string;
  period: string;
}

export interface CandidateDetail {
  candidateId: string;
  educations: Education[];
  careers: Career[];
}

interface CandidateFormProps {
  candidates: Candidate[];
  candidateDetails: CandidateDetail[];
  onCandidatesChange: (candidates: Candidate[]) => void;
  onCandidateDetailsChange: (details: CandidateDetail[]) => void;
}

const generateId = () => Math.random().toString(36).substr(2, 9);

const candidateColumns: ColumnDef<Candidate>[] = [
  { key: 'name', label: '성명', type: 'text', width: '80px' },
  { key: 'birthYear', label: '출생년도', type: 'text', width: '80px' },
  { key: 'currentAffiliation', label: '현소속/직위', type: 'text' },
  { key: 'major', label: '전공분야', type: 'text' },
  { key: 'totalPapers', label: '논문수(총)', type: 'number', width: '80px' },
  { key: 'jcrTop', label: 'JCR상위(%)', type: 'number', width: '90px' },
  { key: 'fwci', label: 'FWCI', type: 'number', width: '70px' },
  { key: 'note', label: '비고', type: 'text' },
];

const educationColumns: ColumnDef<Education>[] = [
  { key: 'school', label: '학교명', type: 'text' },
  { key: 'major', label: '전공', type: 'text' },
  { key: 'year', label: '취득년도', type: 'text', width: '90px' },
];

const careerColumns: ColumnDef<Career>[] = [
  { key: 'institution', label: '기관명', type: 'text' },
  { key: 'position', label: '직위', type: 'text' },
  { key: 'period', label: '기간', type: 'text' },
];

export default function CandidateForm({
  candidates,
  candidateDetails,
  onCandidatesChange,
  onCandidateDetailsChange,
}: CandidateFormProps) {
  const [expandedCandidates, setExpandedCandidates] = useState<Set<string>>(new Set());

  const toggleExpanded = (candidateId: string) => {
    setExpandedCandidates((prev) => {
      const next = new Set(prev);
      if (next.has(candidateId)) {
        next.delete(candidateId);
      } else {
        next.add(candidateId);
      }
      return next;
    });
  };

  const addCandidate = () => {
    const newId = generateId();
    const newCandidate: Candidate = {
      id: newId,
      name: '',
      birthYear: '',
      currentAffiliation: '',
      major: '',
      totalPapers: '',
      jcrTop: '',
      fwci: '',
      note: '',
    };
    onCandidatesChange([...candidates, newCandidate]);
    const newDetail: CandidateDetail = {
      candidateId: newId,
      educations: [],
      careers: [],
    };
    onCandidateDetailsChange([...candidateDetails, newDetail]);
  };

  const deleteCandidate = (id: string) => {
    onCandidatesChange(candidates.filter((c) => c.id !== id));
    onCandidateDetailsChange(candidateDetails.filter((d) => d.candidateId !== id));
    setExpandedCandidates((prev) => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
  };

  const updateCandidate = (id: string, key: keyof Candidate, value: string) => {
    onCandidatesChange(
      candidates.map((c) => (c.id === id ? { ...c, [key]: value } : c))
    );
  };

  const getOrCreateDetail = (candidateId: string): CandidateDetail => {
    return (
      candidateDetails.find((d) => d.candidateId === candidateId) || {
        candidateId,
        educations: [],
        careers: [],
      }
    );
  };

  const updateDetail = (updated: CandidateDetail) => {
    const exists = candidateDetails.find((d) => d.candidateId === updated.candidateId);
    if (exists) {
      onCandidateDetailsChange(
        candidateDetails.map((d) =>
          d.candidateId === updated.candidateId ? updated : d
        )
      );
    } else {
      onCandidateDetailsChange([...candidateDetails, updated]);
    }
  };

  const addEducation = (candidateId: string) => {
    const detail = getOrCreateDetail(candidateId);
    updateDetail({
      ...detail,
      educations: [
        ...detail.educations,
        { id: generateId(), school: '', major: '', year: '' },
      ],
    });
  };

  const deleteEducation = (candidateId: string, eduId: string) => {
    const detail = getOrCreateDetail(candidateId);
    updateDetail({
      ...detail,
      educations: detail.educations.filter((e) => e.id !== eduId),
    });
  };

  const updateEducation = (
    candidateId: string,
    eduId: string,
    key: keyof Education,
    value: string
  ) => {
    const detail = getOrCreateDetail(candidateId);
    updateDetail({
      ...detail,
      educations: detail.educations.map((e) =>
        e.id === eduId ? { ...e, [key]: value } : e
      ),
    });
  };

  const addCareer = (candidateId: string) => {
    const detail = getOrCreateDetail(candidateId);
    updateDetail({
      ...detail,
      careers: [
        ...detail.careers,
        { id: generateId(), institution: '', position: '', period: '' },
      ],
    });
  };

  const deleteCareer = (candidateId: string, careerId: string) => {
    const detail = getOrCreateDetail(candidateId);
    updateDetail({
      ...detail,
      careers: detail.careers.filter((c) => c.id !== careerId),
    });
  };

  const updateCareer = (
    candidateId: string,
    careerId: string,
    key: keyof Career,
    value: string
  ) => {
    const detail = getOrCreateDetail(candidateId);
    updateDetail({
      ...detail,
      careers: detail.careers.map((c) =>
        c.id === careerId ? { ...c, [key]: value } : c
      ),
    });
  };

  return (
    <div className="space-y-6">
      {/* 후보자 심사요청서 테이블 */}
      <div className="section-card">
        <h2 className="section-title">후보자 심사요청서</h2>
        <DynamicTable
          columns={candidateColumns}
          rows={candidates}
          onAddRow={addCandidate}
          onDeleteRow={deleteCandidate}
          onUpdateRow={updateCandidate}
          addLabel="+ 후보자 추가"
          emptyMessage="후보자가 없습니다. 후보자를 추가해주세요."
        />
      </div>

      {/* 학위 및 경력 사항 섹션 */}
      {candidates.length > 0 && (
        <div className="section-card">
          <h2 className="section-title">학위 및 경력 사항</h2>
          <div className="space-y-4">
            {candidates.map((candidate, index) => {
              const detail = getOrCreateDetail(candidate.id);
              const isExpanded = expandedCandidates.has(candidate.id);

              return (
                <div key={candidate.id} className="border border-gray-200 rounded-lg overflow-hidden">
                  <button
                    type="button"
                    onClick={() => toggleExpanded(candidate.id)}
                    className="w-full flex items-center justify-between px-4 py-3 bg-gray-50 hover:bg-gray-100 transition-colors text-left"
                  >
                    <span className="font-medium text-gray-800">
                      {index + 1}. {candidate.name || `후보자 ${index + 1}`}
                      {candidate.currentAffiliation && (
                        <span className="text-gray-500 font-normal ml-2 text-sm">
                          ({candidate.currentAffiliation})
                        </span>
                      )}
                    </span>
                    <span className="text-gray-400 text-xl">
                      {isExpanded ? '▲' : '▼'}
                    </span>
                  </button>

                  {isExpanded && (
                    <div className="p-4 space-y-6 bg-white">
                      {/* 최종학위 */}
                      <div>
                        <h3 className="text-sm font-semibold text-gray-700 mb-3">
                          최종학위
                        </h3>
                        <DynamicTable
                          columns={educationColumns}
                          rows={detail.educations}
                          onAddRow={() => addEducation(candidate.id)}
                          onDeleteRow={(eduId) => deleteEducation(candidate.id, eduId)}
                          onUpdateRow={(eduId, key, value) =>
                            updateEducation(candidate.id, eduId, key as keyof Education, value)
                          }
                          addLabel="+ 학위 추가"
                          emptyMessage="학위 정보가 없습니다."
                        />
                      </div>

                      {/* 경력 */}
                      <div>
                        <h3 className="text-sm font-semibold text-gray-700 mb-3">
                          경력 사항
                        </h3>
                        <DynamicTable
                          columns={careerColumns}
                          rows={detail.careers}
                          onAddRow={() => addCareer(candidate.id)}
                          onDeleteRow={(careerId) => deleteCareer(candidate.id, careerId)}
                          onUpdateRow={(careerId, key, value) =>
                            updateCareer(candidate.id, careerId, key as keyof Career, value)
                          }
                          addLabel="+ 경력 추가"
                          emptyMessage="경력 정보가 없습니다."
                        />
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

