  });

  const [candidates, setCandidates] = useState<Candidate[]>([]);
  const [candidateDetails, setCandidateDetails] = useState<CandidateDetail[]>([]);
  const [progressRecords, setProgressRecords] = useState<ProgressRecord[]>([]);
  const [submitStatus, setSubmitStatus] = useState<SubmitStatus>('idle');
  const [submitMessage, setSubmitMessage] = useState('');

  const addProgressRecord = () => {
    setProgressRecords((prev) => [
      ...prev,
      {
        id: generateId(),
        date: new Date().toISOString().split('T')[0],
        content: '',
        manager: '',
      },
    ]);
  };

  const deleteProgressRecord = (id: string) => {
    setProgressRecords((prev) => prev.filter((p) => p.id !== id));
  };

  const updateProgressRecord = (
    id: string,
    key: keyof ProgressRecord,
    value: string
  ) => {
    setProgressRecords((prev) =>
      prev.map((p) => (p.id === id ? { ...p, [key]: value } : p))
    );
  };

  const onSubmit = async (basicInfo: BasicInfo) => {
    if (candidates.length === 0) {
      setSubmitStatus('error');
      setSubmitMessage('최소 1명 이상의 후보자를 추가해야 합니다.');
      return;
    }

    setSubmitStatus('loading');
    setSubmitMessage('');

    const payload = {
      department: basicInfo.department,
      submittedAt: basicInfo.submittedAt,
      deanName: basicInfo.deanName,
      candidates,
      progressRecords,
      candidateDetails,
      status: 'pending',
    };

    try {
      const res = await fetch('/api/submissions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        throw new Error(errData.message || '서버 오류가 발생했습니다.');
      }

      setSubmitStatus('success');
      setSubmitMessage('성공적으로 제출되었습니다. 관리자에게 전달되었습니다.');
      reset();
      setCandidates([]);
      setCandidateDetails([]);
      setProgressRecords([]);
    } catch (err) {
      setSubmitStatus('error');
      setSubmitMessage(
        err instanceof Error
          ? `제출 중 오류: ${err.message}`
          : '제출 중 알 수 없는 오류가 발생했습니다.'
      );
    }
  };

  return (
    <div>
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-gray-900">교원 초빙 심사요청서 제출</h1>
        <p className="mt-1 text-sm text-gray-500">
          학과의 교원 초빙 후보자 정보를 입력하고 제출해주세요.
        </p>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} noValidate>
        {/* 기본 정보 섹션 */}
        <div className="section-card">
          <h2 className="section-title">기본 정보</h2>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div>
              <label className="form-label" htmlFor="department">
                학과명 <span className="text-red-500">*</span>
              </label>
              <select
                id="department"
                {...register('department', { required: '학과명을 선택해주세요.' })}
                className={`form-input ${errors.department ? 'border-red-400' : ''}`}
              >
                <option value="">학과를 선택하세요</option>
                {DEPARTMENTS.map((d) => (
                  <option key={d} value={d}>
                    {d}
                  </option>
                ))}
              </select>
              {errors.department && (
                <p className="text-red-500 text-xs mt-1">{errors.department.message}</p>
              )}
            </div>

            <div>
              <label className="form-label" htmlFor="submittedAt">
                제출일 <span className="text-red-500">*</span>
              </label>
              <input
                id="submittedAt"
                type="date"
                {...register('submittedAt', { required: '제출일을 입력해주세요.' })}
                className={`form-input ${errors.submittedAt ? 'border-red-400' : ''}`}
              />
              {errors.submittedAt && (
                <p className="text-red-500 text-xs mt-1">{errors.submittedAt.message}</p>
              )}
            </div>

            <div>
              <label className="form-label" htmlFor="deanName">
                학장명 <span className="text-red-500">*</span>
              </label>
              <input
                id="deanName"
                type="text"
                placeholder="학장 성함을 입력하세요"
                {...register('deanName', {
                  required: '학장명을 입력해주세요.',
                  minLength: { value: 2, message: '2자 이상 입력해주세요.' },
                })}
                className={`form-input ${errors.deanName ? 'border-red-400' : ''}`}
              />
              {errors.deanName && (
                <p className="text-red-500 text-xs mt-1">{errors.deanName.message}</p>
              )}
            </div>
          </div>
        </div>

        {/* 후보자 심사요청서 + 학위/경력 */}
        <CandidateForm
          candidates={candidates}
          candidateDetails={candidateDetails}
          onCandidatesChange={setCandidates}
          onCandidateDetailsChange={setCandidateDetails}
        />

        {/* 초빙 진행 경과 섹션 */}
        <div className="section-card">
          <h2 className="section-title">초빙 진행 경과</h2>
          <DynamicTable
            columns={progressColumns}
            rows={progressRecords}
            onAddRow={addProgressRecord}
            onDeleteRow={deleteProgressRecord}
            onUpdateRow={updateProgressRecord}
            addLabel="+ 경과 추가"
            emptyMessage="진행 경과가 없습니다. 경과를 추가해주세요."
          />
        </div>

        {/* 제출 결과 메시지 */}
        {submitStatus === 'success' && (
          <div className="rounded-md bg-green-50 border border-green-200 p-4 mb-4">
            <div className="flex">
              <span className="text-green-600 font-medium">✓ </span>
              <p className="ml-2 text-sm text-green-700">{submitMessage}</p>
            </div>
          </div>
        )}
        {submitStatus === 'error' && (
          <div className="rounded-md bg-red-50 border border-red-200 p-4 mb-4">
            <div className="flex">
              <span className="text-red-600 font-medium">✕ </span>
              <p className="ml-2 text-sm text-red-700">{submitMessage}</p>
            </div>
          </div>
        )}

        {/* 제출 버튼 */}
        <div className="flex justify-end">
          <button
            type="submit"
            disabled={submitStatus === 'loading'}
            className="btn-primary px-8 py-3 text-base"
          >
            {submitStatus === 'loading' ? '제출 중...' : '심사요청서 제출'}
          </button>
        </div>
      </form>
    </div>
  );
}

