'use client';

import React from 'react';

export interface ColumnDef<T> {
  key: keyof T;
  label: string;
  type: 'text' | 'number' | 'date' | 'select';
  options?: string[];
  width?: string;
}

interface DynamicTableProps<T extends { _id: string }> {
  columns: ColumnDef<T>[];
  rows: T[];
  onAddRow: () => void;
  onDeleteRow: (id: string) => void;
  onUpdateRow: (id: string, key: keyof T, value: string) => void;
  addLabel?: string;
  emptyMessage?: string;
}

export default function DynamicTable<T extends { _id: string }>({
  columns,
  rows,
  onAddRow,
  onDeleteRow,
  onUpdateRow,
  addLabel = '+ 행 추가',
  emptyMessage = '데이터가 없습니다. 행을 추가해주세요.',
}: DynamicTableProps<T>) {
  return (
    <div className="w-full">
      <div className="overflow-x-auto rounded-lg border border-gray-200">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-blue-700">
            <tr>
              {columns.map((col) => (
                <th
                  key={String(col.key)}
                  className="px-3 py-3 text-left text-xs font-semibold text-white uppercase tracking-wider whitespace-nowrap"
                  style={col.width ? { width: col.width } : {}}
                >
                  {col.label}
                </th>
              ))}
              <th className="px-3 py-3 text-center text-xs font-semibold text-white uppercase tracking-wider w-14">
                삭제
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-100">
            {rows.length === 0 ? (
              <tr>
                <td
                  colSpan={columns.length + 1}
                  className="px-4 py-6 text-center text-gray-400 text-sm"
                >
                  {emptyMessage}
                </td>
              </tr>
            ) : (
              rows.map((row, rowIndex) => (
                <tr
                  key={row._id}
                  className={rowIndex % 2 === 0 ? 'bg-white' : 'bg-gray-50'}
                >
                  {columns.map((col) => (
                    <td key={String(col.key)} className="px-2 py-1.5">
                      {col.type === 'select' && col.options ? (
                        <select
                          value={String(row[col.key] ?? '')}
                          onChange={(e) =>
                            onUpdateRow(row._id, col.key, e.target.value)
                          }
                          className="input-cell"
                        >
                          <option value="">선택</option>
                          {col.options.map((opt) => (
                            <option key={opt} value={opt}>
                              {opt}
                            </option>
                          ))}
                        </select>
                      ) : (
                        <input
                          type={col.type === 'number' ? 'text' : col.type}
                          value={String(row[col.key] ?? '')}
                          onChange={(e) =>
                            onUpdateRow(row._id, col.key, e.target.value)
                          }
                          className="input-cell"
                          placeholder={col.label}
                        />
                      )}
                    </td>
                  ))}
                  <td className="px-2 py-1.5 text-center">
                    <button
                      type="button"
                      onClick={() => onDeleteRow(row._id)}
                      className="btn-danger"
                      title="행 삭제"
                    >
                      ✕
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
      <div className="mt-3">
        <button
          type="button"
          onClick={onAddRow}
          className="btn-secondary text-sm py-1.5 px-3"
        >
          {addLabel}
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import DynamicTable, { ColumnDef } from './DynamicTable';

export interface DegreeRow {
  _id: string;
  school: string;
  major: string;
  degree_year: string;
  degree_type: string;
}

export interface CareerRow {
  _id: string;
  institution: string;
  position: string;
  period: string;
}

export interface CandidateRow {
  _id: string;
  name: string;
  birth_year: string;
  current_affiliation: string;
  current_position: string;
  major_field: string;
  total_papers: string;
  jcr_ratio: string;
  fwci: string;
  remarks: string;
  degrees: DegreeRow[];
  careers: CareerRow[];
}

interface CandidateFormProps {
  candidates: CandidateRow[];
  onCandidatesChange: (candidates: CandidateRow[]) => void;
}

const generateId = () => Math.random().toString(36).substr(2, 9);

const candidateColumns: ColumnDef<Omit<CandidateRow, 'degrees' | 'careers'> & { _id: string }>[] = [
  { key: 'name', label: '성명', type: 'text', width: '80px' },
  { key: 'birth_year', label: '출생년도', type: 'text', width: '80px' },
  { key: 'current_affiliation', label: '현소속', type: 'text' },
  { key: 'current_position', label: '직위', type: 'text', width: '100px' },
  { key: 'major_field', label: '전공분야', type: 'text' },
  { key: 'total_papers', label: '논문수(총)', type: 'number', width: '80px' },
  { key: 'jcr_ratio', label: 'JCR상위(%)', type: 'number', width: '90px' },
  { key: 'fwci', label: 'FWCI', type: 'number', width: '70px' },
  { key: 'remarks', label: '비고', type: 'text' },
];

const degreeColumns: ColumnDef<DegreeRow>[] = [
  { key: 'school', label: '학교명', type: 'text' },
  { key: 'major', label: '전공', type: 'text' },
  { key: 'degree_year', label: '취득년도', type: 'text', width: '90px' },
  { key: 'degree_type', label: '학위구분', type: 'text', width: '90px' },
];

const careerColumns: ColumnDef<CareerRow>[] = [
  { key: 'institution', label: '기관명', type: 'text' },
  { key: 'position', label: '직위', type: 'text' },
  { key: 'period', label: '기간', type: 'text' },
];

export default function CandidateForm({
  candidates,
  onCandidatesChange,
}: CandidateFormProps) {
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());

  const toggleExpanded = (id: string) => {
    setExpandedIds((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  const addCandidate = () => {
    const newCandidate: CandidateRow = {
      _id: generateId(),
      name: '',
      birth_year: '',
      current_affiliation: '',
      current_position: '',
      major_field: '',
      total_papers: '',
      jcr_ratio: '',
      fwci: '',
      remarks: '',
      degrees: [],
      careers: [],
    };
    onCandidatesChange([...candidates, newCandidate]);
  };

  const deleteCandidate = (id: string) => {
    onCandidatesChange(candidates.filter((c) => c._id !== id));
    setExpandedIds((prev) => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
  };

  const updateCandidate = (id: string, key: keyof CandidateRow, value: string) => {
    onCandidatesChange(
      candidates.map((c) => (c._id === id ? { ...c, [key]: value } : c))
    );
  };

  const updateCandidateNested = (id: string, updater: (c: CandidateRow) => CandidateRow) => {
    onCandidatesChange(candidates.map((c) => (c._id === id ? updater(c) : c)));
  };

  // Degree handlers
  const addDegree = (candidateId: string) => {
    updateCandidateNested(candidateId, (c) => ({
      ...c,
      degrees: [
        ...c.degrees,
        { _id: generateId(), school: '', major: '', degree_year: '', degree_type: '' },
      ],
    }));
  };

  const deleteDegree = (candidateId: string, degreeId: string) => {
    updateCandidateNested(candidateId, (c) => ({
      ...c,
      degrees: c.degrees.filter((d) => d._id !== degreeId),
    }));
  };

  const updateDegree = (candidateId: string, degreeId: string, key: keyof DegreeRow, value: string) => {
    updateCandidateNested(candidateId, (c) => ({
      ...c,
      degrees: c.degrees.map((d) => (d._id === degreeId ? { ...d, [key]: value } : d)),
    }));
  };

  // Career handlers
  const addCareer = (candidateId: string) => {
    updateCandidateNested(candidateId, (c) => ({
      ...c,
      careers: [
        ...c.careers,
        { _id: generateId(), institution: '', position: '', period: '' },
      ],
    }));
  };

  const deleteCareer = (candidateId: string, careerId: string) => {
    updateCandidateNested(candidateId, (c) => ({
      ...c,
      careers: c.careers.filter((ca) => ca._id !== careerId),
    }));
  };

  const updateCareer = (candidateId: string, careerId: string, key: keyof CareerRow, value: string) => {
    updateCandidateNested(candidateId, (c) => ({
      ...c,
      careers: c.careers.map((ca) => (ca._id === careerId ? { ...ca, [key]: value } : ca)),
    }));
  };

  return (
    <div className="space-y-6">
      {/* 후보자 심사요청서 테이블 */}
      <div className="section-card">
        <h2 className="section-title">후보자 심사요청서</h2>
        <DynamicTable
          columns={candidateColumns as ColumnDef<CandidateRow>[]}
          rows={candidates}
          onAddRow={addCandidate}
          onDeleteRow={deleteCandidate}
          onUpdateRow={(id, key, value) => updateCandidate(id, key as keyof CandidateRow, value)}
          addLabel="+ 후보자 추가"
          emptyMessage="후보자가 없습니다. 후보자를 추가해주세요."
        />
      </div>

      {/* 학위 및 경력 사항 섹션 */}
      {candidates.length > 0 && (
        <div className="section-card">
          <h2 className="section-title">학위 및 경력 사항</h2>
          <div className="space-y-3">
            {candidates.map((candidate, index) => {
              const isExpanded = expandedIds.has(candidate._id);
              return (
                <div key={candidate._id} className="border border-gray-200 rounded-lg overflow-hidden">
                  <button
                    type="button"
                    onClick={() => toggleExpanded(candidate._id)}
                    className="w-full flex items-center justify-between px-4 py-3 bg-gray-50 hover:bg-gray-100 transition-colors text-left"
                  >
                    <span className="font-medium text-gray-800">
                      {index + 1}. {candidate.name || `후보자 ${index + 1}`}
                      {candidate.current_affiliation && (
                        <span className="text-gray-500 font-normal ml-2 text-sm">
                          ({candidate.current_affiliation}{candidate.current_position ? ` / ${candidate.current_position}` : ''})
                        </span>
                      )}
                    </span>
                    <span className="text-gray-400">{isExpanded ? '▲' : '▼'}</span>
                  </button>

                  {isExpanded && (
                    <div className="p-4 space-y-5 bg-white">
                      <div>
                        <h3 className="text-sm font-semibold text-gray-700 mb-2">최종학위</h3>
                        <DynamicTable
                          columns={degreeColumns}
                          rows={candidate.degrees}
                          onAddRow={() => addDegree(candidate._id)}
                          onDeleteRow={(id) => deleteDegree(candidate._id, id)}
                          onUpdateRow={(id, key, value) =>
                            updateDegree(candidate._id, id, key as keyof DegreeRow, value)
                          }
                          addLabel="+ 학위 추가"
                          emptyMessage="학위 정보가 없습니다."
                        />
                      </div>
                      <div>
                        <h3 className="text-sm font-semibold text-gray-700 mb-2">경력 사항</h3>
                        <DynamicTable
                          columns={careerColumns}
                          rows={candidate.careers}
                          onAddRow={() => addCareer(candidate._id)}
                          onDeleteRow={(id) => deleteCareer(candidate._id, id)}
                          onUpdateRow={(id, key, value) =>
                            updateCareer(candidate._id, id, key as keyof CareerRow, value)
                          }
                          addLabel="+ 경력 추가"
                          emptyMessage="경력 정보가 없습니다."
                        />
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import DynamicTable, { ColumnDef } from '@/components/DynamicTable';
import CandidateForm, { CandidateRow } from '@/components/CandidateForm';

interface ProgressRow {
  _id: string;
  progress_date: string;
  content: string;
  person_in_charge: string;
}

interface BasicInfo {
  department_name: string;
  submitted_at: string;
  dean_name: string;
}

const DEPARTMENTS = [
  '반도체시스템공학과',
  '전자전기공학부',
  '소프트웨어학과',
  '화학공학생명공학부',
  '기계공학부',
  '건설환경공학부',
  '시스템경영공학과',
  '수학과',
  '물리학과',
  '화학과',
];

const progressColumns: ColumnDef<ProgressRow>[] = [
  { key: 'progress_date', label: '일자', type: 'date', width: '150px' },
  { key: 'content', label: '진행내용', type: 'text' },
  { key: 'person_in_charge', label: '담당자', type: 'text', width: '100px' },
];

const generateId = () => Math.random().toString(36).substr(2, 9);

type SubmitStatus = 'idle' | 'loading' | 'success' | 'error';

export default function DeanPage() {
  const {
    register,
    handleSubmit,
    formState: { errors },
    reset,
  } = useForm<BasicInfo>({
    defaultValues: {
      department_name: '',
      submitted_at: new Date().toISOString().split('T')[0],
      dean_name: '',
    },
  });

  const [candidates, setCandidates] = useState<CandidateRow[]>([]);
  const [progressRecords, setProgressRecords] = useState<ProgressRow[]>([]);
  const [submitStatus, setSubmitStatus] = useState<SubmitStatus>('idle');
  const [submitMessage, setSubmitMessage] = useState('');

  const addProgressRecord = () => {
    setProgressRecords((prev) => [
      ...prev,
      {
        _id: generateId(),
        progress_date: new Date().toISOString().split('T')[0],
        content: '',
        person_in_charge: '',
      },
    ]);
  };

  const deleteProgressRecord = (id: string) => {
    setProgressRecords((prev) => prev.filter((p) => p._id !== id));
  };

  const updateProgressRecord = (id: string, key: keyof ProgressRow, value: string) => {
    setProgressRecords((prev) =>
      prev.map((p) => (p._id === id ? { ...p, [key]: value } : p))
    );
  };

  const onSubmit = async (basicInfo: BasicInfo) => {
    if (candidates.length === 0) {
      setSubmitStatus('error');
      setSubmitMessage('최소 1명 이상의 후보자를 추가해야 합니다.');
      return;
    }

    setSubmitStatus('loading');
    setSubmitMessage('');

    // Map frontend data to API schema
    const payload = {
      department_name: basicInfo.department_name,
      submitted_at: basicInfo.submitted_at,
      dean_name: basicInfo.dean_name,
      candidates: candidates.map((c) => ({
        name: c.name,
        birth_year: c.birth_year ? parseInt(c.birth_year) : undefined,
        current_affiliation: c.current_affiliation || undefined,
        current_position: c.current_position || undefined,
        major_field: c.major_field || undefined,
        total_papers: c.total_papers ? parseInt(c.total_papers) : undefined,
        jcr_ratio: c.jcr_ratio ? parseFloat(c.jcr_ratio) : undefined,
        fwci: c.fwci ? parseFloat(c.fwci) : undefined,
        remarks: c.remarks || undefined,
        degrees: c.degrees.map((d) => ({
          school: d.school || undefined,
          major: d.major || undefined,
          degree_year: d.degree_year ? parseInt(d.degree_year) : undefined,
          degree_type: d.degree_type || undefined,
        })),
        careers: c.careers.map((ca) => ({
          institution: ca.institution || undefined,
          position: ca.position || undefined,
          period: ca.period || undefined,
        })),
      })),
      hiringProgress: progressRecords.map((p) => ({
        progress_date: p.progress_date || undefined,
        content: p.content || undefined,
        person_in_charge: p.person_in_charge || undefined,
      })),
    };

    try {
      const res = await fetch('/api/submissions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        throw new Error(errData.error || '서버 오류가 발생했습니다.');
      }

      setSubmitStatus('success');
      setSubmitMessage('심사요청서가 성공적으로 제출되었습니다. 관리자에게 전달되었습니다.');
      reset();
      setCandidates([]);
      setProgressRecords([]);
    } catch (err) {
      setSubmitStatus('error');
      setSubmitMessage(
        err instanceof Error
          ? `제출 중 오류: ${err.message}`
          : '제출 중 알 수 없는 오류가 발생했습니다.'
      );
    }
  };

  return (
    <div>
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-gray-900">교원 초빙 심사요청서 제출</h1>
        <p className="mt-1 text-sm text-gray-500">
          학과의 교원 초빙 후보자 정보를 입력하고 제출해주세요.
        </p>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} noValidate>
        {/* 기본 정보 섹션 */}
        <div className="section-card">
          <h2 className="section-title">기본 정보</h2>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div>
              <label className="form-label" htmlFor="department_name">
                학과명 <span className="text-red-500">*</span>
              </label>
              <select
                id="department_name"
                {...register('department_name', { required: '학과명을 선택해주세요.' })}
                className={`form-input ${errors.department_name ? 'border-red-400' : ''}`}
              >
                <option value="">학과를 선택하세요</option>
                {DEPARTMENTS.map((d) => (
                  <option key={d} value={d}>
                    {d}
                  </option>
                ))}
              </select>
              {errors.department_name && (
                <p className="text-red-500 text-xs mt-1">{errors.department_name.message}</p>
              )}
            </div>

            <div>
              <label className="form-label" htmlFor="submitted_at">
                제출일 <span className="text-red-500">*</span>
              </label>
              <input
                id="submitted_at"
                type="date"
                {...register('submitted_at', { required: '제출일을 입력해주세요.' })}
                className={`form-input ${errors.submitted_at ? 'border-red-400' : ''}`}
              />
              {errors.submitted_at && (
                <p className="text-red-500 text-xs mt-1">{errors.submitted_at.message}</p>
              )}
            </div>

            <div>
              <label className="form-label" htmlFor="dean_name">
                학장명 <span className="text-red-500">*</span>
              </label>
              <input
                id="dean_name"
                type="text"
                placeholder="학장 성함을 입력하세요"
                {...register('dean_name', {
                  required: '학장명을 입력해주세요.',
                  minLength: { value: 2, message: '2자 이상 입력해주세요.' },
                })}
                className={`form-input ${errors.dean_name ? 'border-red-400' : ''}`}
              />
              {errors.dean_name && (
                <p className="text-red-500 text-xs mt-1">{errors.dean_name.message}</p>
              )}
            </div>
          </div>
        </div>

        {/* 후보자 심사요청서 + 학위/경력 */}
        <CandidateForm
          candidates={candidates}
          onCandidatesChange={setCandidates}
        />

        {/* 초빙 진행 경과 섹션 */}
        <div className="section-card">
          <h2 className="section-title">초빙 진행 경과</h2>
          <DynamicTable
            columns={progressColumns}
            rows={progressRecords}
            onAddRow={addProgressRecord}
            onDeleteRow={deleteProgressRecord}
            onUpdateRow={(id, key, value) =>
              updateProgressRecord(id, key as keyof ProgressRow, value)
            }
            addLabel="+ 경과 추가"
            emptyMessage="진행 경과가 없습니다. 경과를 추가해주세요."
          />
        </div>

        {/* 제출 결과 메시지 */}
        {submitStatus === 'success' && (
          <div className="rounded-md bg-green-50 border border-green-200 p-4 mb-4">
            <p className="text-sm text-green-700">✓ {submitMessage}</p>
          </div>
        )}
        {submitStatus === 'error' && (
          <div className="rounded-md bg-red-50 border border-red-200 p-4 mb-4">
            <p className="text-sm text-red-700">✕ {submitMessage}</p>
          </div>
        )}

        {/* 제출 버튼 */}
        <div className="flex justify-end">
          <button
            type="submit"
            disabled={submitStatus === 'loading'}
            className="btn-primary px-8 py-3 text-base"
          >
            {submitStatus === 'loading' ? '제출 중...' : '심사요청서 제출'}
          </button>
        </div>
      </form>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';

// Types matching API schema (lib/types.ts + API responses)
interface SubmissionRow {
  id: number;
  department_name: string;
  dean_name: string;
  submitted_at: string;
  status: string;
  created_at: string;
  candidate_count?: number;
}

interface DegreeDetail {
  school?: string;
  major?: string;
  degree_year?: number;
  degree_type?: string;
}

interface CareerDetail {
  institution?: string;
  position?: string;
  period?: string;
}

interface CandidateDetail {
  id: number;
  name: string;
  birth_year?: number;
  current_affiliation?: string;
  current_position?: string;
  major_field?: string;
  total_papers?: number;
  jcr_ratio?: number;
  fwci?: number;
  remarks?: string;
  degrees: DegreeDetail[];
  careers: CareerDetail[];
}

interface ProgressDetail {
  progress_date?: string;
  content?: string;
  person_in_charge?: string;
}

interface SubmissionDetail extends SubmissionRow {
  candidates: CandidateDetail[];
  hiringProgress: ProgressDetail[];
}

